import os, json
out=[]
for p in os.listdir('/proc'):
 if not p.isdigit() or p==str(os.getpid()): continue
 try: cmd=open('/proc/'+p+'/cmdline','rb').read().replace(bytes([0]),b' ').decode('utf-8','replace')
 except Exception: continue
 toks=cmd.split()
 if toks and toks[0].endswith('python3') and 'physical_inference_node.py' in cmd and '--run-id' in cmd:
 out.append((int(p), cmd))
print(json.dumps(out))
